  "sim.egg-incubator.title": "Inkubator do jaj",
  "sim.egg-incubator.desc": "Zarządzaj temperaturą, wilgotnością i obracaniem jaj w wylęgarni, aby zmaksymalizować wylęgowość.",
  "sim.dairy-farm.title": "Ferma mleczna",
  "sim.dairy-farm.desc": "Prowadź małą farmę mleczną: harmonogramy karmienia, cykle dojenia i zdrowie stada, aby zmaksymalizować uzysk.",
  "sim.poultry-farm.title": "Ferma drobiu",
  "sim.poultry-farm.desc": "Zarządzaj komercyjną fermą drobiu — karmienie, zdrowie i cele produkcyjne dla stad brojlerów i niosek.",
  "sim.cattle-dairy.title": "Bydło i mleczarstwo",
  "sim.cattle-dairy.desc": "Nadzoruj ranczo i jednostkę mleczną, równoważąc zarządzanie pastwiskami, hodowlę i produkcję mleka.",
  "sim.sheep-farm.title": "Ferma owiec",
  "sim.sheep-farm.desc": "Prowadź farmę owiec przez cykle sezonowe: jagnięta, strzyżenie i sprzedaż na rynku.",
  "sim.network-noc.title": "Sieć NOC",
  "sim.network-noc.desc": "Zachowuj się jak inżynier NOC — diagnozuj i rozwiązuj bieżące incydenty infrastrukturalne pod presją.",
  "sim.mobile-repair.title": "Warsztat naprawy telefonów komórkowych",
  "sim.mobile-repair.desc": "Diagnozuj i naprawiaj smartfony — wymiana ekranów, problemy z baterią i usterki płyty głównej.",
  "sim.laptop-repair.title": "Warsztat naprawy laptopów",
  "sim.laptop-repair.desc": "Diagnozuj i naprawiaj laptopy: usterki sprzętowe, problemy z BIOS-em i wymiana podzespołów.",
  "sim.perfume-lab.title": "Laboratorium Perfum",
  "sim.perfume-lab.desc": "Mieszaj olejki eteryczne i związki aromatyczne, aby tworzyć autorskie zapachy i spełniać standardy jakości.",
  "sim.detergent-lab.title": "Laboratorium detergentów",
  "sim.detergent-lab.desc": "Opracowuj produkty czyszczące — dobieraj środki powierzchniowo czynne, wypełniacze i testy wydajności w ramach budżetu.",
  "sim.skin-care-lab.title": "Laboratorium pielęgnacji skóry",
  "sim.skin-care-lab.desc": "Opracowuj i testuj receptury kosmetyków, spełniając normy bezpieczeństwa i cele skuteczności.",
  "sim.woodworking.title": "Warsztat stolarski",
  "sim.woodworking.desc": "Prowadź własny warsztat stolarski: planuj zlecenia, zarządzaj materiałami i dostarczaj meble na czas oraz w budżecie.",
  "sim.aluminum-glazing.title": "Aluminium i szklenie",
  "sim.aluminum-glazing.desc": "Prowadź firmę zajmującą się wytwarzaniem z aluminium i montażem szkła — od wyceny do zakończenia na miejscu.",
  "sim.global-kitchen.title": "Globalna Kuchnia",
  "sim.global-kitchen.desc": "Zarządzaj kuchnią w restauracji: prowadź menu, harmonogramy personelu, koszty i zadowolenie klientów we wszystkich zmianach obsługi.",
  "sim.chocolate-factory.title": "Fabryka czekolady",
  "sim.chocolate-factory.desc": "Obsługuj fabrykę cukierniczą — pozyskiwanie kakao, planowanie produkcji i kontrola jakości.",
  "sim.solar-energy.title": "Elektrownia energii słonecznej",
  "sim.solar-energy.desc": "Projektuj i obsługuj instalację solarną — dobieraj rozmiar paneli, zarządzaj eksportem do sieci i śledź zwrot z inwestycji (ROI).",
  "sim.hvac-systems.title": "Systemy HVAC",
  "sim.hvac-systems.desc": "Instaluj i serwisuj systemy ogrzewania, wentylacji i klimatyzacji dla budynków komercyjnych.",
  "sim.logistics-supply.title": "Logistyka i łańcuch dostaw",
  "sim.logistics-supply.desc": "Optymalizuj pracę magazynu, planowanie tras floty i relacje z dostawcami, aby osiągać wskaźniki dostaw (KPI).",
  "sim.barber-salon.title": "Salon fryzjerski",
  "sim.barber-salon.desc": "Zarządzaj salonem fryzjerskim: rezerwacje, grafiki pracowników, cennik i strategie utrzymania klientów.",
  "sim.board-surgeon.title": "Chirurg na wezwanie",
  "sim.board-surgeon.desc": "Podejmuj przełomowe decyzje chirurgiczne w symulowanej sali operacyjnej — zarządzanie czasem i bezpieczeństwo pacjenta.",
  "sim.english-journey.title": "English Journey",
  "sim.english-journey.desc": "Prowadź kurs języka angielskiego w uporządkowanym programie, dopasowując go do różnych poziomów umiejętności.",
  "sim.music-training.title": "Studio szkoleniowe muzyczne",
  "sim.music-training.desc": "Prowadź szkołę muzyczną: planuj lekcje, zarządzaj instrumentami i śledź postępy uczniów przed występami.",
  "sim.trade-tycoon.title": "Biznesmen z branży handlowej",
  "sim.trade-tycoon.desc": "Buduj imperium handlowe — kupuj tanio, sprzedawaj drogo, zarządzaj zapasami i przepływem gotówki na wielu rynkach.",
  "sim.vehicle-diagnostics.title": "Symulator diagnostyki i naprawy pojazdu",
  "sim.vehicle-diagnostics.desc": "Diagnozuj kody usterek OBD-II, wykrywaj usterki elektryczne i zarządzaj rzeczywistym procesem naprawy auta.",
  "sim.marine-vessel.title": "Śledzenie statków i logistyka morska",
  "sim.marine-vessel.desc": "Dowodź globalną flotą — śledź jednostki, omijaj korki w porcie, reaguj na sytuacje kryzysowe pogodowe i opóźnienia kanałów.",
