  "jungle.howTo.4": "Przetrwaj wszystkie 8 scenariuszy, aby wygrać!",
  "jungle.scene6": "Widzisz rannego ptaka. Co robisz?",
  "jungle.s6c1": "Ostrożnie go przenoś — może zaprowadzić Cię na ścieżkę (+5 HP, +25 pkt)",
  "jungle.s6c2": "Zostaw go — opieka nad nim marnuje energię (0 HP, +10 pkt)",
  "jungle.scene7": "Rzeka blokuje Ci drogę. Woda wygląda na bardzo szybką.",
  "jungle.s7c1": "Zbuduj tratwę z powalonych kłód (−5 HP, +40 pkt)",
  "jungle.s7c2": "Idź pod prąd, by znaleźć płytkie przejście (+10 HP, +20 pkt)",
  "jungle.scene8": "W oddali widzisz dym.",
  "jungle.s8c1": "Idź w stronę dymu — może to ratunek! (+15 HP, +45 pkt)",
  "jungle.s8c2": "Unikaj go — to może być pożar lasu (−5 HP, +15 pkt)",
  "jungle.scene9": "Zapada noc. Potrzebujesz schronienia.",
  "jungle.s9c1": "Wejdź na wysokie drzewo, aby uchronić się przed drapieżnikami (+10 HP, +30 pkt)",
  "jungle.s9c2": "Zbuduj schronienie na ziemi z gałęziami (−5 HP, +35 pkt)",
  "jungle.scene10": "Znalazłeś owoc, którego nie rozpoznajesz. Bardzo jesteś głodny.",
  "jungle.s10c1": "Zjedz go — jesteś na skraju wyczerpania! (−20 HP, +30 pkt)",
  "jungle.s10c2": "Najpierw przetestuj mały kawałek na skórze (0 HP, +20 pkt)",
  "jungle.scene11": "Na ścieżce zwija się duży wąż.",
  "jungle.s11c1": "Cofnij się powoli i znajdź objazd (+5 HP, +30 pkt)",
  "jungle.s11c2": "Spróbuj go spłoszyć (−25 HP, +40 pkt)",
  "jungle.scene12": "Słyszysz wodospad — Twoje zapasy wody są krytycznie niskie.",
  "jungle.s12c1": "Idź za dźwiękiem, by znaleźć świeżą wodę (+20 HP, +35 pkt)",
  "jungle.s12c2": "Zignoruj to i idź dalej (−15 HP, +20 pkt)",
  "jungle.scene13": "Szybko nadchodzi burza.",
  "jungle.s13c1": "Znajdź wyżej położone miejsce i schron (+10 HP, +25 pkt)",
  "jungle.s13c2": "Idź dalej, aby uciec (−10 HP, +30 pkt)",
  "jungle.scene14": "Trafiasz do jaskini. Jest coraz ciemniej.",
  "jungle.s14c1": "Wejdź do jaskini dla schronienia (+15 HP, +30 pkt)",
  "jungle.s14c2": "Prześpij się pod drzewem — jaskinia może być zajęta (+5 HP, +20 pkt)",
  "jungle.scene15": "Jesteś wyczerpany. Polana przed Tobą wygląda na bezpieczną.",
  "jungle.s15c1": "Odpocznij i odzyskaj siły (+20 HP, +20 pkt)",
  "jungle.s15c2": "Idź dalej — tutaj odpoczynek jest niebezpieczny (−5 HP, +30 pkt)",
  "jungle.scene16": "Znalazłeś stary mapę wyrytą w drzewie.",
  "jungle.s16c1": "Idź zgodnie z kierunkiem z mapy (+5 HP, +40 pkt)",
  "jungle.s16c2": "Zignoruj to — może być przestarzałe (0 HP, +10 pkt)",
  "jungle.scene17": "Dziki wściekle przebiegają przez Twoją ścieżkę.",
  "jungle.s17c1": "Wskocz od razu na najbliższe drzewo (+5 HP, +30 pkt)",
  "jungle.s17c2": "Stój twardo i krzycz (−20 HP, +35 pkt)",
  "jungle.scene18": "Znalazłeś opuszczony obóz z zapasami.",
  "jungle.s18c1": "Weź wszystko, co może się przydać (+20 HP, +50 pkt)",
  "jungle.s18c2": "Zostaw to — ktoś może potrzebować tego później (0 HP, +10 pkt)",
  "jungle.scene19": "Małpa kradnie Ci torbę z jedzeniem!",
  "jungle.s19c1": "Pograj za małpą (−10 HP, +40 pkt)",
  "jungle.s19c2": "Odpuść — to nie warte energii (+0 HP, +15 pkt)",
  "jungle.scene20": "Słyszysz śmigłowiec nad sobą.",
  "jungle.s20c1": "Natychmiast rozpłoń ogień sygnalizacyjny! (+30 HP, +60 pkt)",
  "jungle.s20c2": "Machaj rękami — może Cię zobaczy (+5 HP, +40 pkt)",
